update public.academy_modules set learning_objectives = array['Explain candidate sourcing.', 'Identify appropriate candidate sourcing channels.', 'Create a sourcing strategy from a recruitment requirement.', 'Use basic Boolean search operators.', 'Build useful recruitment search keywords.', 'Evaluate basic candidate-profile relevance.', 'Distinguish strong, partial and weak matches.', 'Maintain accurate sourcing information.', 'Prepare candidates for the screening stage.', 'Create a structured candidate sourcing plan.']::text[] where module_number = 3;
