select id, 1, 'Introduction to Candidate Sourcing', 'What sourcing is, active vs passive candidates and the recruiter''s responsibility.', 'text', 13, true, 'active', '{"blocks": [{"type": "h", "text": "What candidate sourcing means"}, {"type": "p", "text": "Sourcing is the work of finding people who may suit an open requirement and starting a conversation with them. It comes after you understand the JD and before you screen anyone."}, {"type": "h", "text": "Purpose of sourcing"}, {"type": "list", "items": ["Build a pool of relevant people for each requirement.", "Reach suitable candidates before competitors do.", "Give the screening stage good-quality profiles to work with."]}, {"type": "h", "text": "Active vs passive candidates"}, {"type": "terms", "items": [{"term": "Active candidates", "definition": "Currently looking for a job — applying on portals, attending walk-ins, responding quickly."}, {"term": "Passive candidates", "definition": "Employed and not actively looking, but open to the right opportunity. They need a clear, respectful pitch and more follow-up."}]}, {"type": "h", "text": "Why sourcing quality matters"}, {"type": "p", "text": "Ten relevant profiles are worth more than a hundred random ones. Poor sourcing wastes screening time, frustrates hiring managers and gives candidates a bad impression of the company."}, {"type": "h", "text": "Sourcing vs screening"}, {"type": "terms", "items": [{"term": "Sourcing", "definition": "Finding and attracting people who appear to match the requirement, based on available information."}, {"term": "Screening", "definition": "Speaking with the candidate to confirm skills, experience, availability and interest against the JD."}]}, {"type": "h", "text": "Recruiter''s responsibility during sourcing"}, {"type": "list", "items": ["Use only approved sources and follow each platform''s terms of use.", "Respect candidate privacy; use contact details only for genuine opportunities.", "Record the source of every candidate.", "Describe the role accurately in the first message."]}, {"type": "h", "text": "Practical example"}, {"type": "example", "title": "Requirement: 4 Telecallers, Coimbatore, Tamil + English, 0–2 years", "text": "A recruiter who understood the JD searches portals for ''telecaller'' / ''tele sales'' in Coimbatore, asks placed candidates for referrals, and plans a walk-in. A recruiter who skipped the JD searches ''sales'' across Tamil Nadu and spends the day calling field-sales profiles from other cities."}, {"type": "callout", "text": "Sourcing starts with the requirement, not with the search box. Decode the JD first (Module 2)."}]}'::jsonb from public.academy_modules where module_number = 3
