select id, 2, 'Candidate Sourcing Channels', 'Major sourcing channels, when to use them and their limits.', 'text', 18, true, 'active', '{"blocks": [{"type": "p", "text": "No single channel works for every role. Choose channels based on the role level, volume, location and urgency. This lesson is training only — always follow your company''s approved tools and each platform''s rules."}, {"type": "h", "text": "Job portals"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Websites where candidates post CVs and apply for jobs."}, {"term": "When it is useful", "definition": "Most volume and mid-level roles."}, {"term": "Advantages", "definition": "Large pool, search filters, active candidates."}, {"term": "Limitations", "definition": "Outdated CVs, duplicates, high competition."}, {"term": "Candidates it reaches", "definition": "Mostly active candidates across levels."}]}, {"type": "h", "text": "Professional networks"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Online professional profile networks."}, {"term": "When it is useful", "definition": "Specialist, experienced or corporate roles."}, {"term": "Advantages", "definition": "Detailed work history; reach passive talent."}, {"term": "Limitations", "definition": "Lower response rates; message limits."}, {"term": "Candidates it reaches", "definition": "Experienced and passive professionals."}]}, {"type": "h", "text": "Social media sourcing"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Posting or searching on social platforms and community groups."}, {"term": "When it is useful", "definition": "Volume hiring, local roles, younger audiences."}, {"term": "Advantages", "definition": "Wide, fast reach; low cost."}, {"term": "Limitations", "definition": "Less structured information; noise."}, {"term": "Candidates it reaches", "definition": "Freshers, local and entry-level candidates."}]}, {"type": "h", "text": "Employee referrals"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Existing employees or placed candidates recommend people."}, {"term": "When it is useful", "definition": "Any role, especially hard-to-fill ones."}, {"term": "Advantages", "definition": "Higher quality and retention; trust."}, {"term": "Limitations", "definition": "Limited volume; risk of similar backgrounds."}, {"term": "Candidates it reaches", "definition": "Candidates from employees'' networks."}]}, {"type": "h", "text": "Internal databases"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Candidates already in the company''s own records."}, {"term": "When it is useful", "definition": "Every requirement — check first."}, {"term": "Advantages", "definition": "Fast, free, already known."}, {"term": "Limitations", "definition": "Data may be old; needs re-confirmation."}, {"term": "Candidates it reaches", "definition": "Past applicants and earlier-screened candidates."}]}, {"type": "h", "text": "Campus/college sourcing"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Hiring directly through colleges."}, {"term": "When it is useful", "definition": "Fresher and trainee programmes."}, {"term": "Advantages", "definition": "Batch hiring; planned joining dates."}, {"term": "Limitations", "definition": "Seasonal; no experience."}, {"term": "Candidates it reaches", "definition": "Final-year students and fresh graduates."}]}, {"type": "h", "text": "Job fairs"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Multi-employer hiring events."}, {"term": "When it is useful", "definition": "Volume hiring and employer visibility."}, {"term": "Advantages", "definition": "Meet many candidates in a day."}, {"term": "Limitations", "definition": "Cost and effort; mixed relevance."}, {"term": "Candidates it reaches", "definition": "Active job seekers, mostly entry to mid-level."}]}, {"type": "h", "text": "Recruitment events"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Company-run hiring days or drives."}, {"term": "When it is useful", "definition": "Urgent, high-volume requirements."}, {"term": "Advantages", "definition": "Screen and interview on the same day."}, {"term": "Limitations", "definition": "Needs planning and promotion."}, {"term": "Candidates it reaches", "definition": "Local active candidates."}]}, {"type": "h", "text": "Walk-in recruitment"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Candidates come to the office at set times."}, {"term": "When it is useful", "definition": "BPO, retail, telecalling, support roles."}, {"term": "Advantages", "definition": "Quick turnaround; immediate joiners."}, {"term": "Limitations", "definition": "Unpredictable turnout; quality varies."}, {"term": "Candidates it reaches", "definition": "Local, active, entry-level candidates."}]}, {"type": "h", "text": "Direct candidate outreach"}, {"type": "terms", "items": [{"term": "What it is", "definition": "Contacting a specific person about a role."}, {"term": "When it is useful", "definition": "Niche or senior roles; passive candidates."}, {"term": "Advantages", "definition": "Targeted; reaches people not applying."}, {"term": "Limitations", "definition": "Time-consuming; must be respectful and relevant."}, {"term": "Candidates it reaches", "definition": "Passive, experienced candidates."}]}, {"type": "callout", "text": "Start with the internal database and referrals, then add the channels that best fit the role level and volume."}]}'::jsonb from public.academy_modules where module_number = 3
