select id, 3, 'Preparing a Sourcing Strategy', 'Turning a requirement into a prioritised sourcing plan.', 'scenario', 17, true, 'active', '{"blocks": [{"type": "h", "text": "Steps to build a strategy"}, {"type": "steps", "items": [{"title": "Understand the JD", "text": "Read it fully and clarify gaps with the hiring manager."}, {"title": "Identify mandatory criteria", "text": "Non-negotiables: core skill, minimum experience, location."}, {"title": "Identify preferred criteria", "text": "Advantages that rank candidates higher."}, {"title": "Define the target profile", "text": "One sentence describing the ideal candidate."}, {"title": "Decide channels", "text": "Pick 2–4 channels that fit the role."}, {"title": "Define keywords", "text": "Titles, skills and tools, plus their variations."}, {"title": "Define filters", "text": "Location, experience range, qualification and skills."}, {"title": "Prioritise", "text": "Fastest, highest-quality channels first."}, {"title": "Track results", "text": "Count profiles found, contacted, interested and shortlisted per channel."}]}, {"type": "h", "text": "Scenario"}, {"type": "example", "title": "Requirement: 2 Java Developers, Pune (Kharadi), hybrid 3 days office, 3–6 years, Spring Boot mandatory, AWS preferred, up to 14 LPA, notice ≤ 45 days", "text": "The recruiter writes the target profile: ''Pune-based Java backend developer, 3–6 years, Spring Boot and REST APIs, join within 45 days.''"}, {"type": "terms", "items": [{"term": "Mandatory", "definition": "Java, Spring Boot, 3–6 years, Pune or willing to relocate within 45 days."}, {"term": "Preferred", "definition": "AWS, microservices."}, {"term": "Keywords", "definition": "Java developer, Java engineer, backend developer, Spring Boot, REST API, microservices."}, {"term": "Filters", "definition": "Location Pune; experience 3–6 years; B.E./B.Tech/MCA."}, {"term": "Channel priority", "definition": "1. Internal database  2. Job portal search  3. Professional networks  4. Employee referrals."}, {"term": "Tracking", "definition": "Daily count per channel: found / contacted / interested / submitted."}]}, {"type": "callout", "text": "Review your tracker after two days. If a channel produces no interested candidates, change keywords or move effort to another channel."}]}'::jsonb from public.academy_modules where module_number = 3
