select id, 4, 'Search Keywords and Boolean Search Basics', 'Using AND, OR, NOT, quotes and brackets to focus searches.', 'text', 16, true, 'active', '{"blocks": [{"type": "p", "text": "Boolean search uses a few operators to combine keywords. Most job portals and databases support some form of it. Use it only within the features and terms each platform allows."}, {"type": "h", "text": "The operators"}, {"type": "terms", "items": [{"term": "AND", "definition": "Both terms must appear. Narrows the search. Example: Java AND \"Spring Boot\"."}, {"term": "OR", "definition": "Either term may appear. Broadens the search — useful for title variations. Example: Java OR Python."}, {"term": "NOT", "definition": "Excludes a term. Example: developer NOT tester."}, {"term": "\"Exact phrase\"", "definition": "Searches the words together in that order. Example: \"software developer\"."}, {"term": "Parentheses ( )", "definition": "Group terms so OR is evaluated first. Example: (\"software developer\" OR \"software engineer\") AND Java."}]}, {"type": "h", "text": "Basic combinations"}, {"type": "example", "title": "\"software developer\" AND Java", "text": "Profiles that mention the exact title and Java."}, {"type": "example", "title": "(\"software developer\" OR \"software engineer\") AND Java", "text": "Covers both common titles, but still requires Java."}, {"type": "example", "title": "(telecaller OR \"tele sales\" OR \"telesales\") AND (Tamil OR Kannada)", "text": "Volume-hiring search for language-specific telecalling roles."}, {"type": "example", "title": "(\"accounts executive\" OR accountant) AND Tally AND GST NOT intern", "text": "Accounts profiles with Tally and GST, excluding internships."}, {"type": "h", "text": "Narrow vs broaden"}, {"type": "compare", "title": "Adjusting results", "good": "Too many results: add AND terms, use exact phrases, add NOT for unrelated roles.", "bad": "Too few results: add OR variations, remove preferred skills, widen location.", "goodLabel": "Narrow", "badLabel": "Broaden"}, {"type": "callout", "text": "Do not use NOT too aggressively — ''NOT testing'' would also remove good developers who mention unit testing."}]}'::jsonb from public.academy_modules where module_number = 3
