select id, 5, 'Candidate Search and Profile Relevance', 'Judging whether a sourced profile is a strong, partial or weak match.', 'scenario', 15, true, 'active', '{"blocks": [{"type": "h", "text": "What to check on each profile"}, {"type": "list", "items": ["Job title relevance — does the actual work match?", "Skills match — mandatory skills present?", "Experience match — relevant years within range?", "Qualification", "Industry/domain", "Location and willingness to relocate", "Work mode fit", "Notice period", "Career continuity where relevant — note gaps neutrally and ask, never assume", "Any requirement-specific criteria (language, shift, licence)"]}, {"type": "h", "text": "Match levels"}, {"type": "terms", "items": [{"term": "Strong match", "definition": "Meets all mandatory criteria and most preferred ones. Contact first."}, {"term": "Partial match", "definition": "Meets most mandatory criteria; one gap that may be acceptable (e.g. notice slightly longer). Contact and clarify."}, {"term": "Weak match", "definition": "Misses a core mandatory requirement. Do not submit; keep in the database for other roles."}]}, {"type": "h", "text": "Examples (fictional training profiles)"}, {"type": "p", "text": "Requirement: Java Developer, Pune, 3–6 years, Spring Boot mandatory, AWS preferred, notice ≤ 45 days."}, {"type": "example", "title": "Profile A — Strong", "text": "Backend Developer, Pune, 4.5 years Java + Spring Boot, AWS exposure, 30-day notice."}, {"type": "example", "title": "Profile B — Partial", "text": "Software Engineer, Mumbai, 5 years Java + Spring Boot, open to relocation, 60-day notice (negotiable). Clarify relocation and notice before shortlisting."}, {"type": "example", "title": "Profile C — Weak", "text": "QA Engineer, Pune, 5 years, Selenium with Java scripting. Java appears, but the role is testing, not development."}, {"type": "callout", "text": "A profile only shows what the candidate wrote. Relevance at sourcing stage is an estimate — screening confirms it."}]}'::jsonb from public.academy_modules where module_number = 3
