select id, 6, 'Sourcing Quality and Candidate Shortlisting Preparation', 'Practice: compare several profiles against one requirement before screening.', 'practice', 19, true, 'active', '{"blocks": [{"type": "h", "text": "Quality principles"}, {"type": "list", "items": ["Quality over quantity — submit fewer, better profiles.", "Avoid irrelevant profiles that only share a keyword.", "Check for duplicates in the internal database before contacting.", "Read all available information, not just the headline.", "Compare every profile with the JD criteria.", "Record the source for every candidate.", "Maintain ownership — one recruiter owns each candidate per requirement.", "Prepare notes and questions for the screening call.", "Do not assume — if information is missing, mark it ''to confirm''."]}, {"type": "h", "text": "Exercise"}, {"type": "example", "title": "Requirement: Customer Support Executive (Voice), Bengaluru, WFO, rotational shift, Hindi + English, 0–2 years, immediate to 15 days", "text": "Rate each fictional profile as Strong, Partial or Weak and note what to confirm on the screening call."}, {"type": "terms", "items": [{"term": "Profile 1", "definition": "Customer Care Executive, Bengaluru, 1.5 yrs domestic voice, Hindi + English, serving notice (10 days)."}, {"term": "Profile 2", "definition": "Fresher, B.Com 2024, Bengaluru, Hindi + English, no shift preference stated."}, {"term": "Profile 3", "definition": "Chat Support Associate, Mysuru, 2 yrs non-voice, Kannada + English."}, {"term": "Profile 4", "definition": "Customer Care Executive, Bengaluru, 1.5 yrs — same phone number as Profile 1 under a different email."}]}, {"type": "answer", "title": "Model evaluation", "items": [{"term": "Profile 1 — Strong", "definition": "All mandatory criteria met. Confirm comfort with rotational shifts."}, {"term": "Profile 2 — Partial", "definition": "0–2 years allows freshers; confirm rotational shift acceptance and spoken English level."}, {"term": "Profile 3 — Weak", "definition": "No Hindi, non-voice experience and outside Bengaluru. Keep for chat/Kannada roles."}, {"term": "Profile 4 — Duplicate", "definition": "Same person as Profile 1. Merge records; do not contact twice or submit twice."}]}, {"type": "callout", "text": "Duplicates submitted to a client damage credibility. Always search your database by phone and email before outreach."}]}'::jsonb from public.academy_modules where module_number = 3
