select id, 7, 'Candidate Sourcing Documentation and Tracking', 'What to record during sourcing and why accurate records matter.', 'text', 14, true, 'active', '{"blocks": [{"type": "h", "text": "What to record"}, {"type": "terms", "items": [{"term": "Candidate name", "definition": "As the candidate gives it."}, {"term": "Candidate ID", "definition": "Internal reference where applicable."}, {"term": "Source", "definition": "Exact channel — portal, referral (with referrer), walk-in, database."}, {"term": "Requirement", "definition": "Which opening the candidate is considered for."}, {"term": "Recruiter ownership", "definition": "Who owns the candidate for this requirement."}, {"term": "Contact status", "definition": "Not contacted / contacted / no response / call back."}, {"term": "Initial response", "definition": "Interested, not interested (with reason), considering."}, {"term": "Relevant skills", "definition": "Skills confirmed against the JD."}, {"term": "Experience", "definition": "Total and relevant, separately."}, {"term": "Follow-up action", "definition": "Next step and due date."}, {"term": "Candidate status", "definition": "Sourced, screening scheduled, shortlisted, rejected, on hold."}, {"term": "Notes", "definition": "Facts only: notice period, CTC expectation, location preference."}, {"term": "Date/time", "definition": "When each important action happened."}]}, {"type": "h", "text": "Why accuracy matters"}, {"type": "list", "items": ["Prevents duplicate calls and ownership disputes.", "Lets any team member pick up a follow-up.", "Shows which channels actually work.", "Supports audits and client reporting."]}, {"type": "compare", "title": "Writing notes", "good": "''Expects 6 LPA; 30-day notice; prefers Whitefield; call back Thu 4 pm.''", "bad": "''Good guy, seems keen, call later.''", "goodLabel": "Factual", "badLabel": "Vague"}, {"type": "callout", "text": "Never record passwords, login details or unnecessary personal data. Store only what the recruitment process needs."}]}'::jsonb from public.academy_modules where module_number = 3
