select id, 8, 'Build a Candidate Sourcing Plan', 'Practice: prepare a complete sourcing plan, then review the model plan.', 'practice', 20, true, 'active', '{"blocks": [{"type": "h", "text": "The requirement (original training example)"}, {"type": "example", "title": "Email from the hiring manager", "text": "We need 3 Field Sales Executives for our FMCG distribution business in Hyderabad (Secunderabad and Kukatpally beats). Office reporting at 9 am, then field visits to retailers, 6 days a week. Graduates preferred, 12th pass acceptable with experience. 1–4 years in FMCG or beverages field sales is a must. Own two-wheeler with valid licence is mandatory. Telugu and Hindi needed. Salary up to 3.6 LPA plus incentives and petrol allowance. Need joiners within 15 days."}, {"type": "h", "text": "Exercise — prepare these 10 items"}, {"type": "list", "items": ["1. Candidate profile", "2. Mandatory requirements", "3. Preferred requirements", "4. Search keywords", "5. Boolean search string", "6. Recommended sourcing channels", "7. Target candidate profile", "8. Initial relevance criteria", "9. Candidate information to capture", "10. Follow-up preparation"]}, {"type": "answer", "title": "Model Sourcing Plan", "items": [{"term": "1. Candidate profile", "definition": "Field Sales Executive, FMCG, Hyderabad, 1–4 years, 3 openings."}, {"term": "2. Mandatory requirements", "definition": "1–4 yrs FMCG/beverage field sales; own two-wheeler + licence; Telugu and Hindi; Hyderabad-based; join ≤ 15 days; 12th pass minimum."}, {"term": "3. Preferred requirements", "definition": "Graduate; experience on Secunderabad or Kukatpally beats; existing retailer network."}, {"term": "4. Search keywords", "definition": "field sales, sales executive, sales officer, territory sales, FMCG, beverages, distribution, retail sales, beat."}, {"term": "5. Boolean search string", "definition": "(\"field sales\" OR \"sales executive\" OR \"sales officer\" OR \"territory sales\") AND (FMCG OR beverages OR distribution) NOT (\"inside sales\" OR telecaller)"}, {"term": "6. Recommended channels", "definition": "Internal database; job portals filtered to Hyderabad; referrals from current field staff; local social media job groups; walk-in drive if volume is low."}, {"term": "7. Target candidate profile", "definition": "Hyderabad-based FMCG field salesperson with 1–4 years, own bike, fluent Telugu and Hindi, able to join in 15 days."}, {"term": "8. Initial relevance criteria", "definition": "Strong: all mandatory met. Partial: one clarifiable gap (e.g. 20-day notice). Weak: no FMCG field experience or no two-wheeler."}, {"term": "9. Information to capture", "definition": "Name, source, current area, experience (total/FMCG), current company, two-wheeler and licence, languages, notice period, CTC expectation, contact status, next action."}, {"term": "10. Follow-up preparation", "definition": "Script for first call; list of questions to confirm (licence, beat familiarity, 6-day week); follow-up within 24 hours; daily channel tracker."}]}, {"type": "callout", "text": "This plan becomes your screening checklist in Module 4. Share it with the hiring manager before you start calling."}]}'::jsonb from public.academy_modules where module_number = 3
